// Custom Cloudflare Worker entry: the OpenNext handler + the SQLite Durable Object that stores everything.
// @ts-expect-error — generated by `opennextjs-cloudflare build`
import { default as handler } from "./.open-next/worker.js";
import { DurableObject } from "cloudflare:workers";
import { migrateSync, shapeRows, normalizeParams, type SqlQuery, type SqlResult } from "@bias/db";

export class BiasDb extends DurableObject {
  constructor(ctx: DurableObjectState, env: unknown) {
    super(ctx, env as never);
    ctx.blockConcurrencyWhile(async () => {
      migrateSync(this.exec());
    });
  }

  private exec() {
    const sql = this.ctx.storage.sql;
    const storage = this.ctx.storage;
    return {
      exec: (q: string, params: unknown[]) => Array.from(sql.exec(q, ...(normalizeParams(params) as never[])).raw()) as unknown[][],
      transaction: <T,>(fn: () => T): T => storage.transactionSync(fn),
    };
  }

  async query(q: SqlQuery): Promise<SqlResult> {
    const x = this.exec();
    return shapeRows(q.method, x.exec(q.sql, q.params));
  }

  async batch(qs: SqlQuery[]): Promise<SqlResult[]> {
    const x = this.exec();
    return x.transaction(() => qs.map((q) => shapeRows(q.method, x.exec(q.sql, q.params))));
  }
}

export default {
  fetch: handler.fetch,
} satisfies ExportedHandler<CloudflareEnv>;
